{"datasetId":"npMDITpuuR0xzBKzd","items":[{"url":"https://www.federalregister.gov/api/v1/documents/2025-12314.json","fetch":{"loadedUrl":"https://www.federalregister.gov/api/v1/documents/2025-12314.json","loadedTime":"2026-10-08T21:01:56.960Z","httpStatusCode":200,"contentLengthBytes":5397,"contentType":"application/json; charset=utf-8"},"metadata":{"canonicalUrl":"https://www.federalregister.gov/api/v1/documents/2025-12314.json","title":null,"description":null,"author":null,"keywords":null,"languageCode":null,"jsonLd":null,"headers":{"accept-ranges":"bytes","access-control-allow-origin":"*","age":"0","cache-control":"no-store, no-cache, must-revalidate, private","connection":"keep-alive","content-security-policy":"default-src 'self' https:; font-src 'self' https: data:; img-src 'self' https: data: 'report-sample'; object-src 'none'; script-src 'self' https: 'report-sample'; style-src 'self' https: 'report-sample' 'unsafe-inline'","content-type":"application/json; charset=utf-8","date":"Thu, 08 Oct 2026 21:01:56 GMT","feature-policy":"camera 'none'; microphone 'none'; usb 'none'; fullscreen 'self'; payment 'self'","keep-alive":"timeout=5","pragma":"no-cache","referrer-policy":"strict-origin-when-cross-origin","status":"200 OK","strict-transport-security":"max-age=31536000; includeSubDomains; preload","transfer-encoding":"chunked","vary":"Accept-Encoding","x-apify-unblocker-route":"GANYMEDE","x-content-type-options":"nosniff","x-frame-options":"DENY","x-permitted-cross-domain-policies":"none","x-request-id":"Root1-6ac804c4-2a15a74461928ca6572db1e5","x-xss-protection":"0"}},"text":"{\"abstract\":\"The Department of Labor (Department) proposes to remove parts located in Title 29, Chapter V, Subchapter B of the Code of Federal Regulations (CFR) that were not originally issued, or subsequently amended, through notice-and-comment rulemaking. Because these parts consist of interpretive rules and policy statements regarding the Fair Labor Standards Act (FLSA) which do not carry the force and effect of law, the Department believes that these parts, to the extent that they have not benefitted from public comment, should be repurposed as sub- regulatory guidance. The Department seeks comment on what provisions in Subchapter B should be retained in the CFR, as well as what kind of sub-regulatory guidance the Department should use to preserve interpretive rules and policy statements that are removed from the CFR. This summary can be found at https://www.regulations.gov by searching by the RIN: 1235-AA52.\",\"action\":\"Notice of proposed rule; request for comments.\",\"agencies\":[{\"raw_name\":\"DEPARTMENT OF LABOR\",\"name\":\"Labor Department\",\"id\":271,\"url\":\"https://www.federalregister.gov/agencies/labor-department\",\"json_url\":\"https://www.federalregister.gov/api/v1/agencies/271\",\"parent_id\":null,\"slug\":\"labor-department\"},{\"raw_name\":\"Wage and Hour Division\",\"name\":\"Wage and Hour Division\",\"id\":524,\"url\":\"https://www.federalregister.gov/agencies/wage-and-hour-division\",\"json_url\":\"https://www.federalregister.gov/api/v1/agencies/524\",\"parent_id\":271,\"slug\":\"wage-and-hour-division\"}],\"body_html_url\":\"https://www.federalregister.gov/documents/full_text/html/2025/07/02/2025-12314.html\",\"cfr_references\":[{\"chapter\":null,\"citation_url\":null,\"part\":\"775\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"776\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"779\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"782\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"783\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"784\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"789\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"793\",\"title\":29},{\"chapter\":null,\"citation_url\":null,\"part\":\"794\",\"title\":29}],\"citation\":\"90 FR 28985\",\"comment_url\":null,\"comments_c